// ---------------------------------------------------------------------------
//  Antwort für ElevenLabs zusammenbauen
// ---------------------------------------------------------------------------
//  Zwei Wege führen hier durch:
//
//    Normalfall  Die Control-API hat geantwortet. Wir reichen ihre Antwort
//                durch und entfernen nur das interne Beiwerk.
//
//    Notbetrieb  Die Control-API war nicht erreichbar oder hat gemeckert.
//                Dann MUSS hier trotzdem eine vollständige, gültige Antwort
//                herauskommen. Fehlt auch nur eine dynamische Variable,
//                bricht ElevenLabs den Anruf ab — der Anrufer hört ein
//                Klicken und Stille. Ein Agent, der ohne Kalender arbeitet,
//                ist unendlich viel besser als einer, der nicht abnimmt.

const antwort = $input.first().json;
// Bei onError liefert der Node { error: … } statt einer Antwort.
const status = antwort?.error ? 0 : (antwort?.statusCode ?? 0);
if (antwort?.error) console.warn(`Control-API nicht erreichbar: ${antwort.error.message ?? antwort.error}`);
const inhalt = antwort.body ?? {};

if (status >= 200 && status < 300 && inhalt.dynamic_variables) {
  const { _intern, ...sauber } = inhalt;
  return [{ json: { _hinweis: 'normal', _intern: _intern ?? {}, antwort: sauber } }];
}

console.warn(`Control-API nicht verwertbar (HTTP ${status}) — Notbetrieb`);

const jetzt = new Date();
const fmt = (o) => new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin', ...o }).format(jetzt);

// parseInt statt Number: die deutsche Formatierung hängt " Uhr" an, und
// Number('12 Uhr') ist NaN. Damit wären alle Vergleiche unten falsch und der
// Agent grüßte mittags mit "Guten Abend".
const stunde = parseInt(fmt({ hour: '2-digit', hour12: false }), 10) % 24;
const gruss = stunde < 11 ? 'Guten Morgen' : stunde < 18 ? 'Guten Tag' : 'Guten Abend';

// Der Notbetrieb nimmt an und notiert. Er stellt bewusst NICHT durch und
// verspricht keine Termine — beides bräuchte Daten, die gerade fehlen.
return [{
  json: {
    _hinweis: 'notbetrieb',
    _intern: {},
    antwort: {
      type: 'conversation_initiation_client_data',
      dynamic_variables: {
        modus: 'nur_notiz',
        anrufer_name: 'unbekannt',
        anrufer_bekannt: 'nein',
        anrufer_notiz: 'nichts hinterlegt',
        status_hinweis: '',
        durchstellen_moeglich: 'nein',
        heute: fmt({ weekday: 'long', day: 'numeric', month: 'long' }),
        uhrzeit: fmt({ hour: '2-digit', minute: '2-digit', hour12: false }),
      },
      conversation_config_override: {
        agent: {
          first_message: `${gruss}, hier ist der Assistent von Damjan Savić. ` +
            'Er kann gerade nicht selbst ans Telefon — worum geht es denn?',
        },
      },
    },
  },
}];
